import pytest
from candidate import sum_product


class TestSumProduct:
    def test_empty_list_returns_zero_and_one(self):
        assert sum_product([]) == (0, 1)

    def test_single_positive_element(self):
        assert sum_product([5]) == (5, 5)

    def test_single_zero_element(self):
        assert sum_product([0]) == (0, 0)

    def test_single_negative_element(self):
        assert sum_product([-3]) == (-3, -3)

    def test_multiple_positive_integers(self):
        assert sum_product([1, 2, 3, 4]) == (10, 24)

    def test_multiple_integers_with_zero(self):
        assert sum_product([1, 0, 3]) == (4, 0)

    def test_all_zeros(self):
        assert sum_product([0, 0, 0]) == (0, 0)

    def test_negative_integers(self):
        assert sum_product([-1, -2, -3]) == (-6, -6)

    def test_mixed_positive_and_negative(self):
        assert sum_product([1, -2, 3]) == (2, -6)

    def test_two_negative_and_one_positive(self):
        assert sum_product([-1, -2, 4]) == (1, 8)

    def test_single_element_one(self):
        assert sum_product([1]) == (1, 1)

    def test_single_element_minus_one(self):
        assert sum_product([-1]) == (-1, -1)

    def test_repeated_elements(self):
        assert sum_product([2, 2, 2]) == (6, 8)

    def test_large_numbers(self):
        assert sum_product([1000, 1000]) == (2000, 1000000)

    def test_very_large_product(self):
        assert sum_product([10, 10, 10, 10]) == (40, 10000)

    def test_two_elements_positive(self):
        assert sum_product([3, 7]) == (10, 21)

    def test_two_elements_negative(self):
        assert sum_product([-4, -5]) == (-9, 20)

    def test_zero_in_middle(self):
        assert sum_product([2, 3, 0, 4]) == (9, 0)

    def test_zero_at_start(self):
        assert sum_product([0, 1, 2, 3]) == (6, 0)

    def test_zero_at_end(self):
        assert sum_product([1, 2, 3, 0]) == (6, 0)

    def test_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            sum_product(None)

    def test_string_input_raises_type_error(self):
        with pytest.raises(TypeError):
            sum_product("123")

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            sum_product(42)

    def test_tuple_input(self):
        assert sum_product((1, 2, 3)) == (6, 6)

    def test_list_with_float_elements(self):
        assert sum_product([1.5, 2.0]) == (3.5, 3.0)

    def test_list_with_string_elements_raises_error(self):
        with pytest.raises(TypeError):
            sum_product([1, "two", 3])

    def test_list_with_none_elements_raises_error(self):
        with pytest.raises(TypeError):
            sum_product([1, None, 3])

    def test_single_element_large_negative(self):
        assert sum_product([-1000000]) == (-1000000, -1000000)

    def test_elements_sum_to_zero(self):
        assert sum_product([1, -1]) == (0, -1)

    def test_elements_product_to_negative(self):
        assert sum_product([2, -3]) == (-1, -6)

    def test_many_elements(self):
        nums = list(range(1, 11))
        expected_sum = sum(nums)
        expected_prod = 1
        for n in nums:
            expected_prod *= n
        assert sum_product(nums) == (expected_sum, expected_prod)

    def test_returns_tuple_type(self):
        result = sum_product([1, 2, 3])
        assert isinstance(result, tuple)

    def test_tuple_has_length_two(self):
        result = sum_product([1, 2, 3])
        assert len(result) == 2

    def test_result_elements_are_integers(self):
        result = sum_product([1, 2, 3])
        assert isinstance(result[0], int)
        assert isinstance(result[1], int)

    def test_negative_and_positive_mixed_large(self):
        assert sum_product([-100, 200, -300]) == (0, 6000000)
